import * as Phaser from 'phaser';
import type {
  ArenaLayout,
  PlayerProfile,
  SyncedFireZone,
  SyncedMeteorStrike,
  SyncedNukeStrike,
  SyncedStinkCloud,
  TeamId,
  SyncedTeslaDome,
} from '../types';
import { PlayerEntity }       from './PlayerEntity';
import type { OwnerVisualSource, OwnerVisualState } from './OwnerVisualSource';
import type { LightingSystem } from '../effects/LightingSystem';
import type { EntityBurnGpuController } from '../effects/EntityBurnGpuController';
import {
  ARENA_HEIGHT,
  ARENA_OFFSET_X, ARENA_OFFSET_Y,
  ARENA_WIDTH,
  CELL_SIZE, GRID_COLS, GRID_ROWS,
  type ArenaGridRegion,
  getCaptureTheBeerBaseRegion,
  getCaptureTheBeerTeamSpawnRegion,
  isCaptureTheBeerBaseModeActive,
} from '../config';
import { getBaseWorldBounds, getCoopDefenseBases, type BaseSpec } from '../arena/BaseRegistry';

const PREFERRED_OPPONENT_DISTANCE_PX = CELL_SIZE * 10;
const MIN_OPPONENT_DISTANCE_PX = CELL_SIZE * 2;
/** Coop-Defense: Bonus-Reichweite, innerhalb derer ein Spawn als „nah an der Basis" gilt. */
const COOP_BASE_NEAR_SPAWN_RANGE_PX = CELL_SIZE * 10;
/** Stärke des Spawn-Bonus pro Pixel-Abstand-Defizit (überwiegt den Opponent-Distance-Bonus). */
const COOP_BASE_NEAR_SPAWN_WEIGHT = 4.0;
/** Größter bevorzugter Abstand zur aktuell bedrohten Basis. */
const COOP_BASE_MAX_PREFERRED_SPAWN_DISTANCE_PX = CELL_SIZE * 14;
/**
 * Coop-Defense: Sicherheitsabstand zur Angriffsreichweite eines Gegners.
 * Liegt der Spawn-Kandidat näher als (Reichweite + dieser Puffer) am Gegner,
 * wird er als "hartes" Risiko bewertet und nur als allerletzte Wahl genutzt –
 * der Spieler weicht dann lieber etwas weiter von der Basis weg.
 */
const COOP_ENEMY_ATTACK_HARD_BUFFER_PX = CELL_SIZE * 2;
/** Soft-Buffer darüber hinaus: noch unbequem nah, aber zulässig wenn nichts besseres existiert. */
const COOP_ENEMY_ATTACK_SOFT_BUFFER_PX = CELL_SIZE * 4;
const EFFECT_SAFE_BUFFER_PX = Math.round(CELL_SIZE * 0.5);
const WARNING_SAFE_BUFFER_PX = CELL_SIZE;
const TURRET_SAFE_BUFFER_PX = CELL_SIZE;
const PROJECTILE_SOFT_RADIUS_PX = CELL_SIZE * 3;
const EDGE_SOFT_DISTANCE_PX = CELL_SIZE * 2;
const TOP_SPAWN_CHOICES = 8;
const GROUND_HAZARD_SPAWN_CLEARANCE_CELLS = 1;

interface SpawnTurretSnapshot {
  x: number;
  y: number;
  ownerId: string;
  range: number;
}

interface SpawnProjectileSnapshot {
  x: number;
  y: number;
  ownerId: string;
  radius: number;
}

interface SpawnEnemyThreatSnapshot {
  x: number;
  y: number;
  /** Effektive Angriffsreichweite des Gegners in Pixel (0 = harmlos). */
  attackRange: number;
  /** Nächstgelegene lebende Coop-Basis, auf die der Gegner zuläuft. */
  targetBaseId?: string;
  targetBaseDistance?: number;
}

interface SpawnContextSnapshot {
  readonly fires: readonly SyncedFireZone[];
  readonly stinkClouds: readonly SyncedStinkCloud[];
  readonly teslaDomes: readonly SyncedTeslaDome[];
  readonly nukes: readonly SyncedNukeStrike[];
  readonly meteors: readonly SyncedMeteorStrike[];
  readonly turrets: readonly SpawnTurretSnapshot[];
  readonly projectiles: readonly SpawnProjectileSnapshot[];
  /** Coop-Defense: aktive Feindbedrohungen mit Reichweite (leer in anderen Modi). */
  readonly enemyThreats?: readonly SpawnEnemyThreatSnapshot[];
  /** Coop-Defense: IDs der noch lebenden Basen (für Spawn-Fokus und Fallback). */
  readonly livingCoopBaseIds?: ReadonlySet<string>;
  /** Bevorzugter Missionsfokus; Sicherheit und globale Fallbacks bleiben unveraendert. */
  readonly preferredSpawnFocus?: { readonly x: number; readonly y: number };
  readonly isRelevantOpponent?: (playerId: string) => boolean;
  readonly hasLineOfSight?: (sx: number, sy: number, ex: number, ey: number) => boolean;
}

interface SpawnCandidate {
  x: number;
  y: number;
  worldX: number;
  worldY: number;
}

interface SpawnEvaluation {
  candidate: SpawnCandidate;
  coopBaseDistance: number;
  preferredFocusDistance: number;
  nearestOpponentDistance: number;
  nearestProjectileDistance: number;
  edgeDistance: number;
  hardDangerHits: number;
  softDangerHits: number;
  hardTurretHits: number;
  softTurretHits: number;
  hardEnemyHits: number;
  softEnemyHits: number;
  projectilePenalty: number;
  score: number;
}

type SpawnContextProvider = (playerId: string | null) => SpawnContextSnapshot | null;

const EMPTY_SPAWN_CONTEXT: SpawnContextSnapshot = {
  fires: [],
  stinkClouds: [],
  teslaDomes: [],
  nukes: [],
  meteors: [],
  turrets: [],
  projectiles: [],
};

export class PlayerManager implements OwnerVisualSource {
  private scene:   Phaser.Scene;
  private players: Map<string, PlayerEntity> = new Map();
  private layout:  ArenaLayout | null = null;
  private localPlayerId: string | null = null;
  private spawnContextProvider: SpawnContextProvider | null = null;
  private relationshipResolver: ((localPlayerId: string, otherPlayerId: string) => boolean) | null = null;
  private teamResolver: ((playerId: string) => TeamId | null) | null = null;
  private lighting: LightingSystem | null = null;
  private burnGpu: EntityBurnGpuController | null = null;

  constructor(scene: Phaser.Scene) {
    this.scene = scene;
  }

  setLocalPlayerId(id: string): void {
    this.localPlayerId = id;
  }

  /** Reicht die scene-lifetime Beleuchtung an neue und bestehende Entities durch. */
  setLightingSystem(lighting: LightingSystem | null): void {
    this.lighting = lighting;
    for (const entity of this.players.values()) entity.setLightingSystem(lighting);
  }

  /** Reicht den scene-lifetime Brand-Partikelcontroller durch, genau wie die Beleuchtung. */
  setEntityBurnGpuController(controller: EntityBurnGpuController | null): void {
    this.burnGpu = controller;
    for (const entity of this.players.values()) entity.setEntityBurnGpuController(controller);
  }

  setRelationshipResolver(resolver: ((localPlayerId: string, otherPlayerId: string) => boolean) | null): void {
    this.relationshipResolver = resolver;
  }

  setTeamResolver(resolver: ((playerId: string) => TeamId | null) | null): void {
    this.teamResolver = resolver;
  }

  setSpawnContextProvider(provider: SpawnContextProvider | null): void {
    this.spawnContextProvider = provider;
  }

  /**
   * Übergibt das aktuelle Arena-Layout.
   * Muss vor addPlayer() und vor Respawns aufgerufen werden.
   */
  setLayout(layout: ArenaLayout): void {
    this.layout = layout;
  }

  /** Erstellt eine PlayerEntity an einer zufällig freien Arena-Position.
   *  Wird nur aufgerufen wenn isReady === true. */
  addPlayer(profile: PlayerProfile): void {
    if (this.players.has(profile.id)) return;
    const spawn = this.getSpawnPoint(profile.id);
    const entity = new PlayerEntity(
      this.scene, profile,
      ARENA_OFFSET_X + spawn.x,
      ARENA_OFFSET_Y + spawn.y,
      this.localPlayerId !== null && this.resolveIsEnemy(profile.id),
      this.lighting,
    );
    // Die Beleuchtung geht ueber den Konstruktor, der Brandcontroller ueber den Setter – beide
    // sind scene-lifetime und muessen auch bei spaeter dazukommenden Spielern anliegen.
    entity.setEntityBurnGpuController(this.burnGpu);
    this.players.set(profile.id, entity);
  }

  private resolveIsEnemy(otherPlayerId: string): boolean {
    if (this.localPlayerId === null) return true;
    if (this.localPlayerId === otherPlayerId) return false;
    return this.relationshipResolver?.(this.localPlayerId, otherPlayerId) ?? true;
  }

  /** Zerstört die PlayerEntity. */
  removePlayer(id: string): void {
    const entity = this.players.get(id);
    if (entity) {
      entity.destroy();
      this.players.delete(id);
    }
  }

  hasPlayer(id: string): boolean {
    return this.players.has(id);
  }

  getPlayer(id: string): PlayerEntity | undefined {
    return this.players.get(id);
  }

  getAllPlayers(): PlayerEntity[] {
    return Array.from(this.players.values());
  }

  /**
   * Besitzerzustand für Renderer und `ProjectileManager` ({@link OwnerVisualSource}). Der
   * Gameplay-Zweig dieser Grenze; die Lobby liefert denselben Zustand aus ihrer
   * Ambient-Actor-Registry.
   */
  getOwnerVisualState(ownerId: string): OwnerVisualState | null {
    const player = this.players.get(ownerId);
    if (!player) return null;
    return { x: player.sprite.x, y: player.sprite.y, color: player.color, visible: player.sprite.visible };
  }

  /**
   * Gibt eine zufällige freie Arena-Zelle zurück (relative Arena-Koordinaten).
   * Schließt blockierte Zellen (Fels, Trunk) und aktuell belegte Spieler-Zellen aus.
   * Wird sowohl für Initial-Spawn als auch für Respawns verwendet.
   */
  getSpawnPoint(requestingPlayerId: string | null = null): { x: number; y: number } {
    const spawnContext = this.spawnContextProvider?.(requestingPlayerId) ?? EMPTY_SPAWN_CONTEXT;

    if (isCaptureTheBeerBaseModeActive() && requestingPlayerId) {
      const teamId = this.teamResolver?.(requestingPlayerId) ?? null;
      const blockedForBaseSpawn = this.buildBlockedCells(requestingPlayerId);
      const baseSpawn = this.tryGetCaptureTheBeerSpawn(teamId, blockedForBaseSpawn);
      if (baseSpawn) return baseSpawn;
    }

    const blocked = this.buildBlockedCells(requestingPlayerId);
    const free = this.collectFreeCells(blocked);

    if (free.length === 0) {
      return this.getEmergencySpawnOutsideGroundHazard();
    }

    const coopDefenseBase = this.resolveCoopDefenseSpawnBase(spawnContext);
    const evaluations = free.map(candidate => this.evaluateSpawnCandidate(
      candidate,
      requestingPlayerId,
      spawnContext,
      coopDefenseBase,
    ));

    const hasMissionFocus = spawnContext.preferredSpawnFocus !== undefined;
    const focusedEvaluations = hasMissionFocus
      ? evaluations.filter((evaluation) => evaluation.preferredFocusDistance <= COOP_BASE_MAX_PREFERRED_SPAWN_DISTANCE_PX)
      : coopDefenseBase
        ? evaluations.filter((evaluation) => evaluation.coopBaseDistance <= COOP_BASE_MAX_PREFERRED_SPAWN_DISTANCE_PX)
      : evaluations;
    // Ein Missionsfokus ist nur eine Praeferenz. Sind alle nahen Kandidaten hart gefaehrdet,
    // faellt die Auswahl auf die vollstaendige sichere Bewertung zurueck.
    const focusedChoice = this.pickSpawnWithFallbacks(focusedEvaluations, !hasMissionFocus);
    if (focusedChoice) return focusedChoice;

    const globalChoice = focusedEvaluations === evaluations
      ? null
      : this.pickSpawnWithFallbacks(evaluations);
    return globalChoice ?? this.getEmergencySpawnOutsideGroundHazard();
  }

  private pickSpawnWithFallbacks(
    evaluations: readonly SpawnEvaluation[],
    allowDangerousFallbacks = true,
  ): { x: number; y: number } | null {
    if (evaluations.length === 0) return null;
    const relaxedThresholds = this.buildRelaxedOpponentThresholds();

    for (const threshold of relaxedThresholds) {
      const strictMatches = evaluations.filter((evaluation) => (
        evaluation.hardDangerHits === 0
        && evaluation.softDangerHits === 0
        && evaluation.hardTurretHits === 0
        && evaluation.softTurretHits === 0
        && evaluation.hardEnemyHits === 0
        && evaluation.softEnemyHits === 0
        && this.meetsOpponentThreshold(evaluation, threshold)
      ));
      const strictChoice = this.pickCandidate(strictMatches);
      if (strictChoice) return strictChoice;

      const softenedMatches = evaluations.filter((evaluation) => (
        evaluation.hardDangerHits === 0
        && evaluation.hardTurretHits === 0
        && evaluation.hardEnemyHits === 0
        && this.meetsOpponentThreshold(evaluation, threshold)
      ));
      const softenedChoice = this.pickCandidate(softenedMatches);
      if (softenedChoice) return softenedChoice;
    }

    const safeChoice = this.pickCandidate(evaluations.filter((evaluation) => (
      evaluation.hardDangerHits === 0
      && evaluation.hardTurretHits === 0
      && evaluation.hardEnemyHits === 0
      && this.meetsOpponentThreshold(evaluation, MIN_OPPONENT_DISTANCE_PX)
    )));
    if (safeChoice) return safeChoice;
    if (!allowDangerousFallbacks) return null;

    const minimumChoice = this.pickCandidate(evaluations.filter((evaluation) => (
      this.meetsOpponentThreshold(evaluation, MIN_OPPONENT_DISTANCE_PX)
    )));
    if (minimumChoice) return minimumChoice;

    return this.pickCandidate(evaluations);
  }

  private buildBlockedCells(
    requestingPlayerId: string | null,
  ): Set<string> {
    const blocked = new Set<string>();

    // Felsen, Baumstümpfe und Gleise aus dem Layout blockieren
    if (this.layout) {
      for (const r of this.layout.rocks) blocked.add(`${r.gridX}_${r.gridY}`);
      for (const t of this.layout.trees) blocked.add(`${t.gridX}_${t.gridY}`);
      for (const track of this.layout.tracks) {
        blocked.add(`${track.gridX}_${track.gridY}`);
        blocked.add(`${track.gridX + 1}_${track.gridY}`);
      }
      for (const pedestal of this.layout.powerUpPedestals) {
        blocked.add(`${pedestal.gridX}_${pedestal.gridY}`);
      }
      for (const key of this.getGroundHazardSpawnExclusionCells()) blocked.add(key);
    }

    // Coop-Defense: Spieler dürfen nicht auf der Basis oder am Rand spawnen –
    // die Basis ist Verteidigungsobjekt, kein Spawn-Bereich.
    for (const base of getCoopDefenseBases()) {
      const minX = Math.max(0, base.region.minGridX - 1);
      const maxX = Math.min(GRID_COLS - 1, base.region.maxGridX + 1);
      const minY = Math.max(0, base.region.minGridY - 1);
      const maxY = Math.min(GRID_ROWS - 1, base.region.maxGridY + 1);
      for (let gy = minY; gy <= maxY; gy++) {
        for (let gx = minX; gx <= maxX; gx++) {
          blocked.add(`${gx}_${gy}`);
        }
      }
    }

    // Aktuell belegte Spieler-Zellen ausschließen.
    // WICHTIG: Diese Sperre ist team-unabhängig – auch Teamkameraden blockieren
    // ihre Zelle, sonst können im Coop (alle gleiches Team) zwei Spieler
    // dieselbe Spawn-Zelle wählen. Team-Filterung gehört nur ins Scoring
    // (Distanz zu Gegnern in evaluateSpawnCandidate), nicht in die Hartsperre.
    for (const p of this.players.values()) {
      if (!p.sprite.active) continue;
      if (requestingPlayerId && p.id === requestingPlayerId) continue;
      const gx = Math.floor((p.sprite.x - ARENA_OFFSET_X) / CELL_SIZE);
      const gy = Math.floor((p.sprite.y - ARENA_OFFSET_Y) / CELL_SIZE);
      blocked.add(`${gx}_${gy}`);
    }

    return blocked;
  }

  /**
   * Nur fuer den praktisch unerreichbaren Fall eines vollstaendig blockierten Layouts:
   * Dauerfeuer bleibt auch im Notfall tabu, selbst wenn dafuer ein anderes Hindernis
   * als letzte Rueckfallposition in Kauf genommen werden muss.
   */
  private getEmergencySpawnOutsideGroundHazard(): { x: number; y: number } {
    const hazardCells = this.getGroundHazardSpawnExclusionCells();
    for (let gridY = 0; gridY < GRID_ROWS; gridY += 1) {
      for (let gridX = 0; gridX < GRID_COLS; gridX += 1) {
        if (hazardCells.has(`${gridX}_${gridY}`)) continue;
        return {
          x: gridX * CELL_SIZE + CELL_SIZE / 2,
          y: gridY * CELL_SIZE + CELL_SIZE / 2,
        };
      }
    }
    return { x: CELL_SIZE / 2, y: CELL_SIZE / 2 };
  }

  /**
   * Spawn-Sperre ueber *alle* vorbereiteten Gefahrenzellen, unabhaengig vom Event-Lifecycle.
   *
   * Anders als die Bausperre kostet das nichts: Ein Spawnpunkt neben einer noch dormanten Flaeche
   * ist beliebig ersetzbar, waehrend ein Spawn auf einer Flaeche, die Sekunden spaeter zuendet,
   * einen Spieler ohne eigenes Zutun ins Feuer setzt.
   */
  private getGroundHazardSpawnExclusionCells(): Set<string> {
    const excluded = new Set<string>();
    for (const zone of this.layout?.groundHazardZones ?? []) {
      for (const cell of zone.cells) {
        for (
          let offsetY = -GROUND_HAZARD_SPAWN_CLEARANCE_CELLS;
          offsetY <= GROUND_HAZARD_SPAWN_CLEARANCE_CELLS;
          offsetY += 1
        ) {
          for (
          let offsetX = -GROUND_HAZARD_SPAWN_CLEARANCE_CELLS;
          offsetX <= GROUND_HAZARD_SPAWN_CLEARANCE_CELLS;
            offsetX += 1
          ) {
            const gridX = cell.gridX + offsetX;
            const gridY = cell.gridY + offsetY;
            if (gridX < 0 || gridX >= GRID_COLS || gridY < 0 || gridY >= GRID_ROWS) continue;
            excluded.add(`${gridX}_${gridY}`);
          }
        }
      }
    }
    return excluded;
  }

  private collectFreeCells(blocked: ReadonlySet<string>, region?: ArenaGridRegion): SpawnCandidate[] {
    const free: SpawnCandidate[] = [];
    const minGridX = region?.minGridX ?? 0;
    const maxGridX = region?.maxGridX ?? GRID_COLS - 1;
    const minGridY = region?.minGridY ?? 0;
    const maxGridY = region?.maxGridY ?? GRID_ROWS - 1;

    for (let gy = minGridY; gy <= maxGridY; gy++) {
      for (let gx = minGridX; gx <= maxGridX; gx++) {
        if (!blocked.has(`${gx}_${gy}`)) {
          const x = gx * CELL_SIZE + CELL_SIZE / 2;
          const y = gy * CELL_SIZE + CELL_SIZE / 2;
          free.push({
            x,
            y,
            worldX: ARENA_OFFSET_X + x,
            worldY: ARENA_OFFSET_Y + y,
          });
        }
      }
    }

    return free;
  }

  private tryGetCaptureTheBeerSpawn(
    teamId: TeamId | null,
    blocked: ReadonlySet<string>,
  ): { x: number; y: number } | null {
    if (!teamId) return null;

    const baseCandidates = this.collectFreeCells(blocked, getCaptureTheBeerBaseRegion(teamId));
    if (baseCandidates.length > 0) {
      return this.pickRandomSpawn(baseCandidates);
    }

    const teamZoneCandidates = this.collectFreeCells(blocked, getCaptureTheBeerTeamSpawnRegion(teamId));
    if (teamZoneCandidates.length > 0) {
      return this.pickRandomSpawn(teamZoneCandidates);
    }

    return null;
  }

  private pickRandomSpawn(candidates: readonly SpawnCandidate[]): { x: number; y: number } | null {
    if (candidates.length === 0) return null;
    const chosen = candidates[Math.floor(Math.random() * candidates.length)];
    return { x: chosen.x, y: chosen.y };
  }

  private buildRelaxedOpponentThresholds(): number[] {
    const thresholds: number[] = [];
    for (let distance = PREFERRED_OPPONENT_DISTANCE_PX; distance >= MIN_OPPONENT_DISTANCE_PX; distance -= CELL_SIZE) {
      thresholds.push(distance);
    }
    if (thresholds[thresholds.length - 1] !== MIN_OPPONENT_DISTANCE_PX) {
      thresholds.push(MIN_OPPONENT_DISTANCE_PX);
    }
    return thresholds;
  }

  private meetsOpponentThreshold(evaluation: SpawnEvaluation, threshold: number): boolean {
    return evaluation.nearestOpponentDistance >= threshold;
  }

  private pickCandidate(evaluations: readonly SpawnEvaluation[]): { x: number; y: number } | null {
    if (evaluations.length === 0) return null;
    const shuffled = Phaser.Utils.Array.Shuffle([...evaluations]);
    const sorted = shuffled.sort((left, right) => right.score - left.score);
    const bestScore = sorted[0].score;
    const bestScorePool = sorted.filter((evaluation) => Math.abs(evaluation.score - bestScore) < 0.001);
    const choicePool = bestScorePool.length > 0
      ? bestScorePool
      : sorted.slice(0, Math.min(TOP_SPAWN_CHOICES, sorted.length));
    const chosen = choicePool[Math.floor(Math.random() * choicePool.length)];
    return { x: chosen.candidate.x, y: chosen.candidate.y };
  }

  private evaluateSpawnCandidate(
    candidate: SpawnCandidate,
    requestingPlayerId: string | null,
    spawnContext: SpawnContextSnapshot,
    coopDefenseBase: BaseSpec | null,
  ): SpawnEvaluation {
    let nearestOpponentDistance = Number.POSITIVE_INFINITY;
    for (const player of this.players.values()) {
      if (requestingPlayerId && player.id === requestingPlayerId) continue;
      if (!player.sprite.active) continue;
      if (spawnContext.isRelevantOpponent && !spawnContext.isRelevantOpponent(player.id)) continue;
      const distance = Phaser.Math.Distance.Between(candidate.worldX, candidate.worldY, player.sprite.x, player.sprite.y);
      nearestOpponentDistance = Math.min(nearestOpponentDistance, distance);
    }

    if (!Number.isFinite(nearestOpponentDistance)) {
      nearestOpponentDistance = PREFERRED_OPPONENT_DISTANCE_PX;
    }

    const fireDanger = this.countZoneDanger(candidate, spawnContext.fires, EFFECT_SAFE_BUFFER_PX);
    const stinkDanger = this.countZoneDanger(candidate, spawnContext.stinkClouds, EFFECT_SAFE_BUFFER_PX);
    const teslaDanger = this.countZoneDanger(candidate, spawnContext.teslaDomes, WARNING_SAFE_BUFFER_PX);
    const nukeDanger = this.countZoneDanger(candidate, spawnContext.nukes, WARNING_SAFE_BUFFER_PX);
    const meteorDanger = this.countZoneDanger(candidate, spawnContext.meteors, WARNING_SAFE_BUFFER_PX);

    const turretDanger = this.countTurretDanger(candidate, requestingPlayerId, spawnContext);
    const projectileDanger = this.measureProjectileDanger(candidate, requestingPlayerId, spawnContext.projectiles);
    const enemyDanger = this.countEnemyAttackDanger(candidate, spawnContext.enemyThreats ?? []);

    const edgeDistance = Math.min(
      candidate.x,
      ARENA_WIDTH - candidate.x,
      candidate.y,
      ARENA_HEIGHT - candidate.y,
    );

    let score = 0;
    score += Math.min(nearestOpponentDistance, PREFERRED_OPPONENT_DISTANCE_PX) * 2.5;
    score += Math.min(projectileDanger.nearestDistance, PROJECTILE_SOFT_RADIUS_PX * 2) * 0.8;
    score += Math.min(edgeDistance, EDGE_SOFT_DISTANCE_PX) * 0.7;

    let coopBaseDistance = Number.POSITIVE_INFINITY;
    if (coopDefenseBase) {
      const bounds = getBaseWorldBounds(coopDefenseBase.region);
      const bx = bounds.x + bounds.width / 2;
      const by = bounds.y + bounds.height / 2;
      coopBaseDistance = Phaser.Math.Distance.Between(candidate.worldX, candidate.worldY, bx, by);
      if (coopBaseDistance < COOP_BASE_NEAR_SPAWN_RANGE_PX) {
        score += (COOP_BASE_NEAR_SPAWN_RANGE_PX - coopBaseDistance) * COOP_BASE_NEAR_SPAWN_WEIGHT;
      }
      score -= Math.max(0, coopBaseDistance - COOP_BASE_NEAR_SPAWN_RANGE_PX) * 0.8;
    }

    const preferredFocusDistance = spawnContext.preferredSpawnFocus
      ? Phaser.Math.Distance.Between(
        candidate.worldX,
        candidate.worldY,
        spawnContext.preferredSpawnFocus.x,
        spawnContext.preferredSpawnFocus.y,
      )
      : Number.POSITIVE_INFINITY;
    if (Number.isFinite(preferredFocusDistance)) {
      score += Math.max(0, COOP_BASE_NEAR_SPAWN_RANGE_PX - preferredFocusDistance) * COOP_BASE_NEAR_SPAWN_WEIGHT;
      score -= Math.max(0, preferredFocusDistance - COOP_BASE_NEAR_SPAWN_RANGE_PX) * 0.8;
    }

    if (edgeDistance < EDGE_SOFT_DISTANCE_PX) {
      score -= (EDGE_SOFT_DISTANCE_PX - edgeDistance) * 2.2;
    }

    score -= projectileDanger.penalty * 3.0;
    score -= (fireDanger.softHits + stinkDanger.softHits + teslaDanger.softHits + nukeDanger.softHits + meteorDanger.softHits) * 260;
    score -= (fireDanger.hardHits + stinkDanger.hardHits + teslaDanger.hardHits + nukeDanger.hardHits + meteorDanger.hardHits) * 2600;
    score -= turretDanger.softHits * 320;
    score -= turretDanger.hardHits * 2800;
    score -= enemyDanger.softHits * 340;
    score -= enemyDanger.hardHits * 3000;

    return {
      candidate,
      coopBaseDistance,
      preferredFocusDistance,
      nearestOpponentDistance,
      nearestProjectileDistance: projectileDanger.nearestDistance,
      edgeDistance,
      hardDangerHits: fireDanger.hardHits + stinkDanger.hardHits + teslaDanger.hardHits + nukeDanger.hardHits + meteorDanger.hardHits,
      softDangerHits: fireDanger.softHits + stinkDanger.softHits + teslaDanger.softHits + nukeDanger.softHits + meteorDanger.softHits,
      hardTurretHits: turretDanger.hardHits,
      softTurretHits: turretDanger.softHits,
      hardEnemyHits: enemyDanger.hardHits,
      softEnemyHits: enemyDanger.softHits,
      projectilePenalty: projectileDanger.penalty,
      score,
    };
  }

  private resolveCoopDefenseSpawnBase(spawnContext: SpawnContextSnapshot): BaseSpec | null {
    // Gespawnt wird an den eigenen Basen; an der Gegnerbasis waere es die schlechteste Wahl.
    const coopBases = getCoopDefenseBases().filter((base) => base.faction !== 'hostile' && base.role !== 'outpost' && base.role !== 'spawn-point');
    if (coopBases.length === 0) return null;

    const livingIds = spawnContext.livingCoopBaseIds;
    const livingBases = livingIds
      ? coopBases.filter((base) => livingIds.has(base.id))
      : coopBases;
    if (livingBases.length === 0) return null;

    const pressureByBaseId = new Map<string, number>();
    for (const enemy of spawnContext.enemyThreats ?? []) {
      if (!enemy.targetBaseId || (livingIds && !livingIds.has(enemy.targetBaseId))) continue;
      const targetBase = livingBases.find((base) => base.id === enemy.targetBaseId);
      if (!targetBase) continue;
      const distance = enemy.targetBaseDistance ?? Number.POSITIVE_INFINITY;
      const pressureRange = enemy.attackRange + COOP_ENEMY_ATTACK_SOFT_BUFFER_PX;
      if (distance > pressureRange) continue;
      const pressure = 1 + Math.max(0, pressureRange - distance) / CELL_SIZE;
      pressureByBaseId.set(enemy.targetBaseId, (pressureByBaseId.get(enemy.targetBaseId) ?? 0) + pressure);
    }

    let selectedBase: BaseSpec | null = null;
    let selectedPressure = 0;
    for (const base of livingBases) {
      const pressure = pressureByBaseId.get(base.id) ?? 0;
      if (pressure > selectedPressure) {
        selectedBase = base;
        selectedPressure = pressure;
      }
    }
    if (selectedBase) return selectedBase;

    let leftmost = livingBases[0];
    for (const base of livingBases) {
      if (base.region.minGridX < leftmost.region.minGridX) leftmost = base;
    }
    return leftmost;
  }

  /**
   * Coop-Defense: zählt Treffer in Angriffsreichweite eines Gegners.
   *  - hardHits: Kandidat liegt innerhalb (Reichweite + harter Sicherheitspuffer).
   *  - softHits: zusätzlich noch innerhalb des weicheren Puffers.
   * Treibt im Coop-Modus dafür, dass Spieler beim Spawn lieber etwas weiter
   * von der Basis zurücktreten, statt direkt vor einem heranrückenden Gegner
   * zu landen.
   */
  private countEnemyAttackDanger(
    candidate: SpawnCandidate,
    enemies: readonly SpawnEnemyThreatSnapshot[],
  ): { hardHits: number; softHits: number } {
    let hardHits = 0;
    let softHits = 0;
    for (const enemy of enemies) {
      if (enemy.attackRange <= 0) continue;
      const distance = Phaser.Math.Distance.Between(candidate.worldX, candidate.worldY, enemy.x, enemy.y);
      const hardLimit = enemy.attackRange + COOP_ENEMY_ATTACK_HARD_BUFFER_PX;
      if (distance <= hardLimit) {
        hardHits += 1;
        continue;
      }
      if (distance <= hardLimit + COOP_ENEMY_ATTACK_SOFT_BUFFER_PX) {
        softHits += 1;
      }
    }
    return { hardHits, softHits };
  }

  private countZoneDanger(
    candidate: SpawnCandidate,
    zones: readonly { x: number; y: number; radius: number }[],
    safeBufferPx: number,
  ): { hardHits: number; softHits: number } {
    let hardHits = 0;
    let softHits = 0;

    for (const zone of zones) {
      const distance = Phaser.Math.Distance.Between(candidate.worldX, candidate.worldY, zone.x, zone.y);
      if (distance <= zone.radius) {
        hardHits += 1;
        continue;
      }
      if (distance <= zone.radius + safeBufferPx) {
        softHits += 1;
      }
    }

    return { hardHits, softHits };
  }

  private countTurretDanger(
    candidate: SpawnCandidate,
    requestingPlayerId: string | null,
    spawnContext: SpawnContextSnapshot,
  ): { hardHits: number; softHits: number } {
    let hardHits = 0;
    let softHits = 0;

    for (const turret of spawnContext.turrets) {
      if (requestingPlayerId && turret.ownerId === requestingPlayerId) continue;
      const distance = Phaser.Math.Distance.Between(candidate.worldX, candidate.worldY, turret.x, turret.y);
      const hasSight = spawnContext.hasLineOfSight
        ? spawnContext.hasLineOfSight(turret.x, turret.y, candidate.worldX, candidate.worldY)
        : true;
      if (!hasSight) continue;

      if (distance <= turret.range) {
        hardHits += 1;
        continue;
      }
      if (distance <= turret.range + TURRET_SAFE_BUFFER_PX) {
        softHits += 1;
      }
    }

    return { hardHits, softHits };
  }

  private measureProjectileDanger(
    candidate: SpawnCandidate,
    requestingPlayerId: string | null,
    projectiles: readonly SpawnProjectileSnapshot[],
  ): { nearestDistance: number; penalty: number } {
    let nearestDistance = Number.POSITIVE_INFINITY;
    let penalty = 0;

    for (const projectile of projectiles) {
      if (requestingPlayerId && projectile.ownerId === requestingPlayerId) continue;
      const distance = Phaser.Math.Distance.Between(candidate.worldX, candidate.worldY, projectile.x, projectile.y);
      nearestDistance = Math.min(nearestDistance, distance);

      const dangerRadius = Math.max(PROJECTILE_SOFT_RADIUS_PX, projectile.radius);
      if (distance <= dangerRadius) {
        penalty += dangerRadius - distance;
      }
    }

    if (!Number.isFinite(nearestDistance)) {
      nearestDistance = PROJECTILE_SOFT_RADIUS_PX * 2;
    }

    return { nearestDistance, penalty };
  }
}
